import React, { useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

function Navbar() {
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <nav className="navbar navbar-expand navbar-light bg-light px-4">
      <Link className="navbar-brand" to="/">Natura Alhambra</Link>

      <div className="navbar-nav ms-auto">
        {!user && (
          <>
            <Link className="nav-link" to="/houses">Casas</Link>
            <Link className="nav-link" to="/login">Iniciar sesión</Link>
            <Link className="nav-link" to="/register">Registrarse</Link>
          </>
        )}

        {user && user.role === 'user' && (
          <>
            <Link className="nav-link" to="/houses">Casas</Link>
            <Link className="nav-link" to="/reservations">Mis Reservas</Link>
            <button className="btn btn-outline-danger btn-sm ms-2" onClick={handleLogout}>
              Cerrar sesión
            </button>
          </>
        )}

        {user && user.role === 'admin' && (
          <>
            <Link className="nav-link" to="/">Inicio</Link>
            <Link className="nav-link" to="/admin">Panel Admin</Link>
            <button className="btn btn-outline-danger btn-sm ms-2" onClick={handleLogout}>
              Cerrar sesión
            </button>
          </>
        )}
      </div>
    </nav>
  );
}

export default Navbar;
